SELECT COUNT(*) as total_followups FROM follow_ups;
SELECT COUNT(*) as leads_with_followup_date FROM leads WHERE follow_up_date IS NOT NULL;
SELECT f.id, f.lead_id, f.due_date, f.status, f.title, l.name as lead_name FROM follow_ups f JOIN leads l ON f.lead_id = l.id WHERE f.status = 'Pending' LIMIT 10;

